using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>() — strongly-typed metadata access
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> => Type: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) TryGetTypeInfo<T>() — safe probe, no exception if unavailable
//    With the default resolver, Person resolves fine:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded: {info!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> returned false");

// Now use a source-gen context that only knows about Person.
// Querying for an unregistered type (string[]) won't throw — it just returns false.
var limited = new JsonSerializerOptions { TypeInfoResolver = SmallContext.Default };

if (limited.TryGetTypeInfo<string[]>(out JsonTypeInfo<string[]>? arrayInfo))
    Console.WriteLine($"TryGetTypeInfo<string[]> succeeded: {arrayInfo!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<string[]> returned false (type not in context)");

// Records & source-gen context
public record Person(string Name, int Age);

